def smallest_after_removal(num: str, k: int) -> str:
    stack = []                                 # kept digits, never decreasing
    for d in num:
        while k and stack and stack[-1] > d:   # a bigger digit right before a smaller one
            stack.pop()
            k -= 1
        stack.append(d)
    if k:
        stack = stack[:-k]                     # no drop left to fix: cut from the end
    return "".join(stack).lstrip("0") or "0"
